<?php
// functions.php - functions used in the API endpoints
require_once 'config.php';
require_once 'connect.php';

function getLeaderboard($conn) {
	$sql = "SELECT player_name, score_string FROM leaderboard WHERE score > 0 ORDER BY score DESC";
	$result = $conn->query($sql);
	$leaderboard = array();
	if ($result && $result->num_rows > 0) {
		while($row = $result->fetch_assoc()) {
			$leaderboard[] = $row;
		}
	}
	return $leaderboard;
}

/*
 * Verifies the HMAC-SHA256 token generated by the Unity client (dataManager.GenerateToken).
 * The client signs JsonUtility.ToJson() of the values, so the JSON must be rebuilt with the
 * same key order, string values, and no escaped slashes/unicode for the hashes to match.
 */
function verifyToken($token, $data, $secretKey) {
    if (!is_string($token) || $token === '' || empty($secretKey)) {
        return false;
    }

    $json = json_encode($data, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    $expected = hash_hmac('sha256', $json, $secretKey);

    // Constant-time comparison to avoid timing attacks
    return hash_equals($expected, strtolower($token));
}

function savePlayerData($conn, $playerName, $playerWallet, $score, $scoreString, $token) {
    // Data to verify (must match the data used to generate the token on the client)
    $data_to_verify = array(
        'playerName' => (string)$playerName,
        'playerWallet' => (string)$playerWallet,
        'score' => (string)$score,
        'scoreString' => (string)$scoreString,
    );

    // Verify the token
    if (!verifyToken($token, $data_to_verify, SECRET_KEY)) {
        return false; // Authentication failed
    }

    // Ensure the score is a valid, non-negative number
    if (!is_numeric($score)) {
        return false;
    }
    $score = max(0, (float)$score);

    // Insert the player data using a prepared statement (prevents SQL injection)
    $stmt = $conn->prepare("INSERT INTO leaderboard (player_name, player_wallet, score, score_string, updated) VALUES (?, ?, ?, ?, CURRENT_TIMESTAMP)");
    if (!$stmt) {
        return false; // Error preparing the query
    }

    $stmt->bind_param('ssds', $playerName, $playerWallet, $score, $scoreString);
    $saved = $stmt->execute();
    $stmt->close();

    return $saved;
}
?>
